const MAX_UTF8_VARCHAR_BYTE_LENGTH = 32000
const DEFAULT_FASTLOAD_MAX_SESSION_COUNT = 8
const MAX_FASTLOAD_ERROR_TABLE_ROW_COUNT = math.MaxInt32
const MAX_FASTLOAD_ERROR_TABLE_ARRAY_LENGTH = 64000 // max column length

var regexFastLoadInsertValuesStatement = regexp.MustCompile ("(?is)\\s*INSERT\\s+INTO\\s+(?:([^\"][^\\s.]*|\"(?:\"\"|[^\"])*\")\\s*\\.\\s*)?([^\"][^\\s]*|\"(?:\"\"|[^\"])*\")\\s*(?:\\((.*)\\))?\\s*(?:VALUES)?\\s*\\([\\s?,]+\\)\\s*(?:;\\s*)?")

var _ fastLoadManager = &fastLoadManagerBase {} // implements fastLoadManager

type fastLoadManagerBase struct {

	m_appRows                   *TeradataRows // parent rows and link to parent connection
	m_appCon                    *TeradataConnection // parent connection
	m_preparedRows              *TeradataRows // prepared rows needed to hold column (parameter) metadata
	m_controlSession            *TeradataConnection // DBC/SQL partition TERA connection needed to begin and end FastLoad
	m_teraCon                   *TeradataConnection // DBC/SQL partition TERA connection needed to select from FastLoad error table 1 while fastloading
	m_fastloadCon               []*TeradataConnection // array of FastLoad partition connections needed to send data
	m_aBindMetadata             [] bindMetadata // the metadata of the data to be inserted
	m_nFastLoadConIndex         int // an index into the array of FastLoad partition connections
	m_asWarnings                []string // any warning generated by GoSQL FastLoad that may be useful to application
	m_bWarningsAtNew            bool // warnings while creating an instance of fastLoadManagerBase
	m_asWarningsAtTypeCast      []string // warnings while evaluating Teradata type cast
	m_bSaveErrorsWarnings       bool // if auto-commit true, save errors and warnings
	m_sTableName                string // the name of the database table to be fastloaded
	m_sTableNameErr1            string // the name of the first of two database tables used for storing errors while fastloading
	m_sTableNameErr2            string // the name of the second of two database tables used for storing errors while fastloading
	m_sBeginLoading             string // the BEGIN LOADING statement to be used with FastLoad
	m_sUsingInsertValues        string // the USING clause INSERT statement to be used with FastLoad
	m_bConnected                bool // indicates whether connections needed to FastLoad were created
	m_bFastloading              bool // indicates whether FastLoad has begun
	m_bCheckFastloadErrorTable2 bool // indicates whether to check FastLoad error table 2
	m_nCurrentRowNumber         int32 // the value to insert for RowNumber
	m_uNumTotalRowsSent         uint64 // the total number of rows sent with FastLoad
	m_bAlreadyAutoCommitted     bool // indicates whether auto-commit was on during executeInsert
	m_bBatchInsert              bool // indicates whether this is a batch insert
	m_nVectorColumnBoundVarbyte int // one-based first Vector column number with bound VARBYTE value, zero means no such column
	m_nVectorColumnBoundVarchar int // one-based first Vector column number with bound VARCHAR value, zero means no such column

} // end type fastLoadManagerBase

func (mgr *fastLoadManagerBase) alreadyAutoCommitted   () bool                     { return mgr.m_bAlreadyAutoCommitted }
func (mgr *fastLoadManagerBase) fastloading            () bool                     { return mgr.m_bFastloading }
func (mgr *fastLoadManagerBase) getAppCon              () *TeradataConnection      { return mgr.m_appCon }
func (mgr *fastLoadManagerBase) getBindMetadata        () [] bindMetadata          { return mgr.m_aBindMetadata }
func (mgr *fastLoadManagerBase) getControlSession      () *TeradataConnection      { return mgr.m_controlSession }
func (mgr *fastLoadManagerBase) getWarnings            () [] string                { return mgr.m_asWarnings }
func (mgr *fastLoadManagerBase) hadWarningsAtNew       () bool                     { return mgr.m_bWarningsAtNew }
func (mgr *fastLoadManagerBase) getWarningsAtTypeCast  () [] string                { return mgr.m_asWarningsAtTypeCast }
func (mgr *fastLoadManagerBase) isBatchInsert          () bool                     { return mgr.m_bBatchInsert }
func (mgr *fastLoadManagerBase) isConnected            () bool                     { return mgr.m_bConnected }
func (mgr *fastLoadManagerBase) saveErrorsAndWarnings  () bool                     { return mgr.m_bSaveErrorsWarnings }
func (mgr *fastLoadManagerBase) setFileImporter        (fileImporter)              { /* do nothing */ }
func (mgr *fastLoadManagerBase) setWarnings            (asWarnings [] string)      { mgr.m_asWarnings = asWarnings }
func (mgr *fastLoadManagerBase) setWarningsAtNew       (b bool)                    { mgr.m_bWarningsAtNew = b }

// Note: This pointer-receiver method will not work with a value inside an interface, which we do not expect or intend.

func (fldManager *fastLoadManagerBase) String () string { // satisfies fmt.Stringer

	return fmt.Sprintf("fldManager=%p key=%v %v", fldManager, fldManager.m_appRows.m_sNativeSQL, fldManager.m_appRows)

} // end method String

func (fldManager *fastLoadManagerBase) Value () fastLoadManager {

	return fldManager

} // end method Value

func (fldManager *fastLoadManagerBase) preferredDataType(dataType uint16) uint16 {

	switch dataType {
		case T_BYTE,
			 T_LONG_VARBYTE:
			return T_VARBYTE
		case T_CHAR,
			 T_LONG_VARCHAR:
			return T_VARCHAR
		case T_DECIMAL:
			return T_NUMBER
		default:
			return dataType
	}

} // end method preferredDataType

func newFastLoadManager (appRows *TeradataRows, ctx context.Context, aBindValues [] driver.NamedValue) (fastLoadManager, error) {

	var sWarning string
	var err error

	fldManager := &fastLoadManagerBase {
		m_appRows           : appRows,
		m_appCon            : appRows.m_stmt.m_con,
	}

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.newFastLoadManager %v", fldManager.m_appRows))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.newFastLoadManager m_sTableName=%v %v sWarning=%v", fldManager.m_sTableName, fldManager, sWarning)) } ()
	}

	// Note: In the future, verify here that no AutoGeneratedKeys have been requested. If AutoGeneratedKeys have been requested,
	// then set a warning that says "Cannot FastLoad because auto-generated key retrieval was requested, but is not supported"

	if !fldManager.m_appRows.m_bWantSIP || !fldManager.m_appRows.m_bSendSIP {

		msg := "Cannot FastLoad because StatementInfo parcel support is not available"

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (520, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 504, msg)
		}

		return fldManager, err
	}

	fldManager.m_preparedRows, err = fldManager.prepareInsert(ctx)
	if err != nil { return fldManager, err }

	if fldManager.m_preparedRows.m_uActivityType != 2 { // 2=INSERT

		msg := "Cannot FastLoad because statement is not an INSERT"

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (521, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 505, msg)
		}

		return fldManager, err
	}

	err = fldManager.m_preparedRows.NextResultSet()
	if err == nil {
		msg := "Cannot FastLoad a multi-statement request"

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (522, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 506, msg)
		}

		return fldManager, err

	} else if errors.Is (err, io.EOF) {
		err = nil

	} else {
		return fldManager, err
	}

	if len(fldManager.m_preparedRows.m_aParamMetadata) == 0 {

		msg := "Cannot FastLoad because no metadata is available"

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (523, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 507, msg)
		}

		return fldManager, err
	}

	if ! regexFastLoadInsertValuesStatement.MatchString(fldManager.m_appRows.m_sNativeSQL) {

		msg := "Cannot FastLoad because the INSERT statement does not match the required syntax"

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (524, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 508, msg)
		}

		return fldManager, err
	}

	if fldManager.m_appRows.m_fileImporter != nil {
		return newFastLoadManagerFileImport (fldManager, fldManager.m_appRows.m_fileImporter)
	}

	// Calculate the maximum IndicData parcel size, excluding the parcel header
	// Add 1 for RowNumber parameter and add 4 for RowNumber INTEGER
	anMaxDataParcelSize := [] uint64 { uint64(((len(fldManager.m_preparedRows.m_aParamMetadata) + 1 + 7) / 8) + 4) }

	var unquotedDbName string
	var unquotedTableName string
	for i := 0; i < len(fldManager.m_preparedRows.m_aParamMetadata); i++ {
		colMetadata := fldManager.m_preparedRows.m_aParamMetadata[i]
		if (i == 0) {
			unquotedDbName = colMetadata.M_sDatabaseName
			unquotedTableName = colMetadata.M_sObjectName
			fldManager.m_sTableName = doubleQuote(unquotedDbName) + "." + doubleQuote(unquotedTableName)
		}

		fldManager.patchColumnMetadata (&colMetadata, i, aBindValues)

		var colTypeCast string
		colTypeCast, err = fldManager.getTeradataTypeCast(i + 1, colMetadata, fldManager.preferredDataType(colMetadata.M_uCookedDataType), colMetadata.M_uByteCount, anMaxDataParcelSize)
		if err != nil || colTypeCast == "" { return fldManager, err }
	}

	if fldManager.m_nVectorColumnBoundVarbyte != 0 && fldManager.m_nVectorColumnBoundVarchar != 0 {

		msg := fmt.Sprintf("Cannot FastLoad %v Vector column %v with bound VARBYTE value and Vector column %v with bound VARCHAR value", fldManager.m_sTableName, fldManager.m_nVectorColumnBoundVarbyte, fldManager.m_nVectorColumnBoundVarchar)

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (571, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 572, msg)
		}

		return fldManager, err
	}

	if fldManager.m_appCon.m_config.M_uMaxUsingDataSizeInBytes <= 64230 && anMaxDataParcelSize[0] > 64000 {

		msg := fmt.Sprintf("Cannot FastLoad because the potential row data size of %v bytes exceeds 64000 bytes", anMaxDataParcelSize[0])

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (525, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 509, msg)
		}

		return fldManager, err
	}

	errTableDbase := func ()(string) { if fldManager.m_appRows.m_sErrorTableDatabase != "" { return fldManager.m_appRows.m_sErrorTableDatabase } ; return unquotedDbName } ()
	fldManager.m_sTableNameErr1 = doubleQuote(errTableDbase) + "." + doubleQuote(unquotedTableName + fldManager.m_appRows.m_sErrorTable1Suffix)
	fldManager.m_sTableNameErr2 = doubleQuote(errTableDbase) + "." + doubleQuote(unquotedTableName + fldManager.m_appRows.m_sErrorTable2Suffix)
	fldManager.m_sBeginLoading = "BEGIN LOADING " + fldManager.m_sTableName + " ERRORFILES " + fldManager.m_sTableNameErr1 + ", " + fldManager.m_sTableNameErr2 + " WITH INTERVAL"

	return fldManager, err

} // end func newFastLoadManager

func (fldManager *fastLoadManagerBase) patchColumnMetadata (colMetadata *columnMetadata, i int, aBindValues [] driver.NamedValue) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.patchColumnMetadata m_sTableName=%v i=%v m_nVectorColumnBoundVarbyte=%v m_nVectorColumnBoundVarchar=%v colMetadata=%v", fldManager.m_sTableName, i, fldManager.m_nVectorColumnBoundVarbyte, fldManager.m_nVectorColumnBoundVarchar, colMetadata))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.patchColumnMetadata m_sTableName=%v i=%v m_nVectorColumnBoundVarbyte=%v m_nVectorColumnBoundVarchar=%v colMetadata=%v", fldManager.m_sTableName, i, fldManager.m_nVectorColumnBoundVarbyte, fldManager.m_nVectorColumnBoundVarchar, colMetadata)) } ()
	}

	if fldManager.m_appCon.hasDebugLog () {
		debugLog(fmt.Sprintf("patchColumnMetadata: len(aBindValues)=%v", len (aBindValues)))
	}

	bBoundVarbyte := func () (bOutput bool) {

		if len (aBindValues) > 0 {

			switch aaBatchValues := aBindValues [0].Value.(type) {

				case [][] driver.NamedValue:
					if len (aaBatchValues) > 0 && len (aaBatchValues [0]) > i {
						bOutput = aaBatchValues [0][i].Value.(TeradataValue).CookedDataType () == T_VARBYTE
					}

				case [][] any:
					if len (aaBatchValues) > 0 && len (aaBatchValues [0]) > i {
						_, bOutput = aaBatchValues [0][i].([] byte)
					}
			} // end switch
		} // end if aBindValues

		return

	} () // end bBoundVarbyte

	bVectorColumn := colMetadata.M_uUDTKind == 3 /* Internal UDT */ && strings.EqualFold (colMetadata.M_sUDTName, "SYSUDTLIB.Vector")
	if bVectorColumn {
		if bBoundVarbyte {
			colMetadata.M_uCookedDataType = T_VARBYTE
			colMetadata.M_uByteCount      = 64000
			if fldManager.m_nVectorColumnBoundVarbyte == 0 { fldManager.m_nVectorColumnBoundVarbyte = i + 1 }
		} else { // assume bound VARCHAR
			colMetadata.M_uCookedDataType = T_VARCHAR
			colMetadata.M_uByteCount      = MAX_UTF8_VARCHAR_BYTE_LENGTH
			if fldManager.m_nVectorColumnBoundVarchar == 0 { fldManager.m_nVectorColumnBoundVarchar = i + 1 }
		}

		_, _, _, _, colMetadata.M_sTypeName = dataTypeInfo (colMetadata.M_uCookedDataType)
	}
} // end method patchColumnMetadata

func (fldManager *fastLoadManagerBase) prepareInsert (ctx context.Context) (rows *TeradataRows, err error) {

	sQuery := "{fn teradata_rpo(S)}{fn teradata_fake_result_sets_off}" + fldManager.m_appRows.m_sNativeSQL // 'S'=PrepareParameterizedSQL

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.prepareInsert sQuery=%v", sQuery))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.prepareInsert sQuery=%v %v", sQuery, rows)) } ()
	}

	stmt, err := newTeradataStatement(fldManager.m_appCon, ctx, sQuery)
	if err != nil { return }

	rows, err = newTeradataRows(stmt, ctx, nil, true)
	if err != nil { return }

	err = rows.Close()
	if err != nil { return }

	return

} // end method prepareInsert

func (fldManager *fastLoadManagerBase) preferredVarCharLength(dataType uint16, precision uint8, scale uint8) uint16 {

	switch dataType {
		case T_BIGINT,
			 T_BYTEINT,
			 T_INTEGER,
			 T_SMALLINT:
			return uint16(precision + 1) // plus 1 for +/- sign
		case T_DECIMAL,
			 T_NUMBER:
			if precision == 40 {
				precision = 130
			}
			if scale == 0 {
				return uint16(precision + 1) // plus 1 for +/- sign
			} else {
				return uint16(precision + 2) // plus 1 for +/- sign and plus 1 for decimal point
			}
		case T_FLOAT:
			return uint16(len(strconv.FormatFloat(math.MaxFloat64, 'E', -1, 64)) + 1) // plus 1 for +/- sign
		default:
			return uint16(0)
	}

} // end method preferredVarCharLength

func (fldManager *fastLoadManagerBase) getTeradataTypeCast(col int, colMetadata columnMetadata, bindCookedDataType uint16, bindByteCount uint64, anMaxDataParcelSize []uint64) (colTypeCast string, err error) {

	var sWarning string

	colTypeName := colMetadata.M_sTypeName
	colCookedDataType := colMetadata.M_uCookedDataType
	colByteCount := colMetadata.M_uByteCount
	colPrecision := colMetadata.M_uPrecision
	colScale := colMetadata.M_uScale
	bindTypeName := fldManager.getTeradataTypeName(bindCookedDataType)

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.getTeradataTypeCast m_sTableName=%v col=%v type=%v (cookedType=%v, byteCount=%v, scale=%v) bind type=%v (cookedType=%v, byteCount=%v) anMaxDataParcelSize[0]=%v",
			fldManager.m_sTableName, col, colTypeName, colCookedDataType, colByteCount, colScale, bindTypeName, bindCookedDataType, bindByteCount, anMaxDataParcelSize[0]))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.getTeradataTypeCast m_sTableName=%v col=%v colTypeCast=%v anMaxDataParcelSize[0]=%v sWarning=%v",
			fldManager.m_sTableName, col, colTypeCast, anMaxDataParcelSize[0], sWarning)) } ()
	}

	if fldManager.m_appCon.hasDebugLog () {
		debugLog(fmt.Sprintf("getTeradataTypeCast incoming: m_sTableName=%v col=%v colMetadata=%+v", fldManager.m_sTableName, col, colMetadata))
		debugLog(fmt.Sprintf("getTeradataTypeCast processed: colCookedDataType=%v colByteCount=%v", colCookedDataType, colByteCount))
	}

	switch colCookedDataType {

		case T_BIGINT,
			 T_BYTEINT,
			 T_DECIMAL, // supported as target column type, but not as bind type
			 T_FLOAT,
			 T_INTEGER,
			 T_NUMBER,
			 T_SMALLINT:

			switch bindCookedDataType {
				case T_BIGINT,
					 T_BYTEINT,
					 T_FLOAT,
					 T_INTEGER,
					 T_NUMBER,
					 T_SMALLINT:

					colTypeCast = bindTypeName
					anMaxDataParcelSize[0] += bindByteCount

				case T_CHAR,
					 T_VARCHAR,
					 T_LONG_VARCHAR:

					nLength := fldManager.preferredVarCharLength(colCookedDataType, colPrecision, colScale)
					colTypeCast = fmt.Sprintf("VARCHAR(%v)", nLength)
					anMaxDataParcelSize[0] += uint64(nLength + 2) // plus 2-byte length

				default:
					msg := fmt.Sprintf("Bound parameter %v type %v (%v) is not supported with target column type %v (%v)",
						col,
						bindTypeName,
						bindCookedDataType,
						colTypeName,
						colCookedDataType)

					if fldManager.m_appRows.m_bTryFastLoad {
						sWarning = fldManager.m_appCon.makeDriverWarning (527, msg)
						fldManager.m_asWarningsAtTypeCast = append(fldManager.m_asWarningsAtTypeCast, sWarning)

					} else {
						err = fldManager.m_appCon.makeDriverError (nil, 516, msg)
					}

					return
			}

		case T_BYTE,
			 T_VARBYTE,
			 T_LONG_VARBYTE:

			if bindCookedDataType == fldManager.preferredDataType(colCookedDataType) || bindCookedDataType == T_CHAR || bindCookedDataType == T_VARCHAR || bindCookedDataType == T_LONG_VARCHAR {
				colTypeCast = fmt.Sprintf("VARBYTE(%v)", colByteCount)
				anMaxDataParcelSize[0] += colByteCount + 2 // plus 2-byte length

			} else {

				msg := fmt.Sprintf("Bound parameter %v type %v (%v) is not supported with target column type %v (%v)",
					col,
					bindTypeName,
					bindCookedDataType,
					colTypeName,
					colCookedDataType)

				if fldManager.m_appRows.m_bTryFastLoad {
					sWarning = fldManager.m_appCon.makeDriverWarning (527, msg)
					fldManager.m_asWarningsAtTypeCast = append(fldManager.m_asWarningsAtTypeCast, sWarning)

				} else {
					err = fldManager.m_appCon.makeDriverError (nil, 516, msg)
				}

				return
			}

		case T_CHAR,
			 T_VARCHAR,
			 T_LONG_VARCHAR:

			if bindCookedDataType == fldManager.preferredDataType(colCookedDataType) {
				// This code is specific to UTF8 and would differ for other session character sets, e.g. nLength = colByteCount for ASCII and UTF16
				nLength := minUint64(colByteCount, MAX_UTF8_VARCHAR_BYTE_LENGTH)
				colTypeCast = fmt.Sprintf("VARCHAR(%v)", nLength)
				anMaxDataParcelSize[0] += nLength + 2 // plus 2-byte length

			} else {

				msg := fmt.Sprintf("Bound parameter %v type %v (%v) is not supported with target column type %v (%v)",
					col,
					bindTypeName,
					bindCookedDataType,
					colTypeName,
					colCookedDataType)

				if fldManager.m_appRows.m_bTryFastLoad {
					sWarning = fldManager.m_appCon.makeDriverWarning (527, msg)
					fldManager.m_asWarningsAtTypeCast = append(fldManager.m_asWarningsAtTypeCast, sWarning)

				} else {
					err = fldManager.m_appCon.makeDriverError (nil, 516, msg)
				}

				return
			}

		case T_DATE_ANSI,
			 T_DATE_INTEGER:

			if bindCookedDataType == T_DATE_ANSI {
				colTypeCast = "CHAR(10)"
				anMaxDataParcelSize[0] += 10
			} else if bindCookedDataType == T_DATE_INTEGER {
				colTypeCast = bindTypeName
				anMaxDataParcelSize[0] += bindByteCount
			} else if bindCookedDataType == T_VARCHAR {
				colTypeCast = "VARCHAR(10)"
				anMaxDataParcelSize[0] += 10 + 2 // plus 2-byte length
			} else {

				msg := fmt.Sprintf("Bound parameter %v type %v (%v) is not supported with target column type %v (%v)",
					col,
					bindTypeName,
					bindCookedDataType,
					colTypeName,
					colCookedDataType)

				if fldManager.m_appRows.m_bTryFastLoad {
					sWarning = fldManager.m_appCon.makeDriverWarning (527, msg)
					fldManager.m_asWarningsAtTypeCast = append(fldManager.m_asWarningsAtTypeCast, sWarning)

				} else {
					err = fldManager.m_appCon.makeDriverError (nil, 516, msg)
				}

				return
			}

		case T_TIME,
			 T_TIME_WITH_TIME_ZONE,
			 T_TIMESTAMP,
			 T_TIMESTAMP_WITH_TIME_ZONE,
			 T_INTERVAL_YEAR,
			 T_INTERVAL_YEAR_TO_MONTH,
			 T_INTERVAL_MONTH,
			 T_INTERVAL_DAY,
			 T_INTERVAL_DAY_TO_HOUR,
			 T_INTERVAL_DAY_TO_MINUTE,
			 T_INTERVAL_DAY_TO_SECOND,
			 T_INTERVAL_HOUR,
			 T_INTERVAL_HOUR_TO_MINUTE,
			 T_INTERVAL_HOUR_TO_SECOND,
			 T_INTERVAL_MINUTE,
			 T_INTERVAL_MINUTE_TO_SECOND,
			 T_INTERVAL_SECOND:

			if bindCookedDataType == colCookedDataType  {
				colTypeCast = fmt.Sprintf("CHAR(%v)", colByteCount)
				anMaxDataParcelSize[0] += colByteCount
			} else if bindCookedDataType == T_VARCHAR {
				colTypeCast = fmt.Sprintf("VARCHAR(%v)", colByteCount)
				anMaxDataParcelSize[0] += colByteCount + 2 // plus 2-byte length
			} else {

				msg := fmt.Sprintf("Bound parameter %v type %v (%v) is not supported with target column type %v (%v)",
					col,
					bindTypeName,
					bindCookedDataType,
					colTypeName,
					colCookedDataType)

				if fldManager.m_appRows.m_bTryFastLoad {
					sWarning = fldManager.m_appCon.makeDriverWarning (527, msg)
					fldManager.m_asWarningsAtTypeCast = append(fldManager.m_asWarningsAtTypeCast, sWarning)

				} else {
					err = fldManager.m_appCon.makeDriverError (nil, 516, msg)
				}

				return
			}

		case T_PERIOD_DATE,
			 T_PERIOD_TIME,
			 T_PERIOD_TIME_WITH_TIME_ZONE,
			 T_PERIOD_TIMESTAMP,
			 T_PERIOD_TIMESTAMP_WITH_TIME_ZONE:

			digits := 0
			if colScale > 0 {
				digits = (int(colScale) + 1) * 2 // plus 1 for the decimal point '.' and times 2 for the two time/timestamp values in a period
			}

			if bindCookedDataType == colCookedDataType  {
				colTypeCast = bindTypeName
				anMaxDataParcelSize[0] += bindByteCount
			} else if bindCookedDataType == T_VARCHAR && colCookedDataType == T_PERIOD_DATE {
				colTypeCast = fmt.Sprintf("VARCHAR(%v)", 28) // e.g. "('1970-01-02', '1973-04-05')"
				anMaxDataParcelSize[0] += 28 + 2 // plus 2-byte length
			} else if bindCookedDataType == T_VARCHAR && colCookedDataType == T_PERIOD_TIME {
				colTypeCast = fmt.Sprintf("VARCHAR(%v)", 24 + digits) // e.g. "('11:22:33.123456', '22:33:44.123456')"
				anMaxDataParcelSize[0] += uint64(24 + digits + 2) // plus 2-byte length
			} else if bindCookedDataType == T_VARCHAR && colCookedDataType == T_PERIOD_TIME_WITH_TIME_ZONE {
				colTypeCast = fmt.Sprintf("VARCHAR(%v)", 36 + digits) // e.g. "('11:22:33.123456+05:30', '22:33:44.123456+05:30')"
				anMaxDataParcelSize[0] += uint64(36 + digits + 2) // plus 2-byte length
			} else if bindCookedDataType == T_VARCHAR && colCookedDataType == T_PERIOD_TIMESTAMP {
				colTypeCast = fmt.Sprintf("VARCHAR(%v)", 46 + digits) // e.g. "('1970-01-02 03:04:05.123456', '1976-07-08 09:10:11.123456')"
				anMaxDataParcelSize[0] += uint64(46 + digits + 2) // plus 2-byte length
			} else if bindCookedDataType == T_VARCHAR && colCookedDataType == T_PERIOD_TIMESTAMP_WITH_TIME_ZONE {
				colTypeCast = fmt.Sprintf("VARCHAR(%v)", 58 + digits) // e.g. "('1970-01-02 03:04:05.123456+05:30', '1976-07-08 09:10:11.123456+05:30')"
				anMaxDataParcelSize[0] += uint64(58 + digits + 2) // plus 2-byte length
			} else {

				msg := fmt.Sprintf("Bound parameter %v type %v (%v) is not supported with target column type %v (%v)",
					col,
					bindTypeName,
					bindCookedDataType,
					colTypeName,
					colCookedDataType)

				if fldManager.m_appRows.m_bTryFastLoad {
					sWarning = fldManager.m_appCon.makeDriverWarning (527, msg)
					fldManager.m_asWarningsAtTypeCast = append(fldManager.m_asWarningsAtTypeCast, sWarning)

				} else {
					err = fldManager.m_appCon.makeDriverError (nil, 516, msg)
				}

				return
			}

	}

	if colTypeCast == "" {

		msg := fmt.Sprintf("Cannot FastLoad because a data type of %v in column %v of the destination database table is not supported",
			colTypeName,
			col)

		if fldManager.m_appRows.m_bTryFastLoad {
			sWarning = fldManager.m_appCon.makeDriverWarning (526, msg)
			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)

		} else {
			err = fldManager.m_appCon.makeDriverError (nil, 510, msg)
		}

		return
	}

	return

} // end method getTeradataTypeCast

func (fldManager *fastLoadManagerBase) getUsingInsertValues (aBindValues [] driver.NamedValue) (usingInsertValues string, err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.getUsingInsertValues m_sTableName=%v", fldManager.m_sTableName))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.getUsingInsertValues usingInsertValues=%v", usingInsertValues)) } ()
	}

	// Calculate the maximum IndicData parcel size, excluding the parcel header
	// Add 1 for RowNumber parameter and add 4 for RowNumber INTEGER
	anMaxDataParcelSize := [] uint64 { uint64(((len(fldManager.m_preparedRows.m_aParamMetadata) + 1 + 7) / 8) + 4) }

	var unquotedDbName string
	var unquotedTableName string
	usingClause := "USING "
	insertStmt := " INSERT INTO "
	valuesList := " VALUES ( "
	for i := 0; i < len(fldManager.m_preparedRows.m_aParamMetadata); i++ {
		colMetadata := fldManager.m_preparedRows.m_aParamMetadata[i]
		bindMetadata := fldManager.m_fastloadCon[0].m_fastloadBindMetadata[i]

		fldManager.patchColumnMetadata (&colMetadata, i, aBindValues)

		var colTypeCast string
		colTypeCast, err = fldManager.getTeradataTypeCast(i + 1, colMetadata, bindMetadata.m_uCookedDataType, bindMetadata.m_uByteCount, anMaxDataParcelSize)
		if err != nil || colTypeCast == "" {
			for j := range fldManager.m_fastloadCon {
				fldManager.m_fastloadCon[j].m_fastloadBindMetadata = nil
			}
			return
		}

		if (i == 0) {
			unquotedDbName = colMetadata.M_sDatabaseName
			unquotedTableName = colMetadata.M_sObjectName
			insertStmt += doubleQuote(unquotedDbName) + "." + doubleQuote(unquotedTableName) + " ( "
		} else {
			usingClause += ", "
			insertStmt  += ", "
			valuesList  += ", "
		}

		unquotedColumnName := colMetadata.M_sName
		usingClause += doubleQuote("F_" + unquotedColumnName) + " (" + colTypeCast + ")"
		insertStmt  += doubleQuote(unquotedColumnName)
		valuesList  += ":" + doubleQuote("F_" + unquotedColumnName)
	}

	usingClause += ", " + doubleQuote("RowNumber") + " (INTEGER)"
	insertStmt += " )"
	valuesList += " )"

	if !(fldManager.m_appCon.m_config.M_uMaxUsingDataSizeInBytes > uint32(64230)) && anMaxDataParcelSize[0] > 64000 {

		err = fldManager.m_controlSession.makeDriverError (nil, 509,
			fmt.Sprintf ("Cannot FastLoad because the potential row data size of %v bytes exceeds 64000 bytes",
				anMaxDataParcelSize[0]))
	}

	usingInsertValues = usingClause + insertStmt + valuesList

	return

} // end method getUsingInsertValues

func (fldManager *fastLoadManagerBase) getSessionsCount (requestedSessions uint32, ctx context.Context, helpSessionResult [] driver.Value) (permittedSessions uint32, err error) {

	var sWarning string
	ampCnt := fldManager.m_controlSession.m_config.M_uAMPCount

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.getSessionsCount m_sTableName=%v ampCnt=%v requestedSessions=%v", fldManager.m_sTableName, ampCnt, requestedSessions))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.getSessionsCount m_sTableName=%v permittedSessions=%v sWarning=%v", fldManager.m_sTableName, permittedSessions, sWarning)) } ()
	}

	bUseCheckWorkload := fldManager.m_appCon.m_config.M_uCheckWorkloadSupport >= 1 && (fldManager.m_appRows.m_bIsGoverned || fldManager.m_appCon.m_config.M_uTDWMFailFastSupport >= 1)
	if bUseCheckWorkload {

		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}SET QUERY_BAND='UtilityName=JDBCL;' FOR SESSION", nil)
		if err != nil { return }

		queryBandArray := getQueryBandFromHelpSessionResult (helpSessionResult)

		if len (queryBandArray [QUERY_BAND_SESSION_INDEX]) > 0 {
			updateQueryband := fmt.Sprintf ("{fn teradata_rpo(E)}SET QUERY_BAND='%v' UPDATE FOR SESSION", queryBandArray [QUERY_BAND_SESSION_INDEX])
			_, err = fldManager.m_controlSession.ExecContext (ctx, updateQueryband, nil)
			if err != nil { return }
		}

		sCheckWorkload := fmt.Sprintf ("{fn teradata_rpo(E)}CHECK WORKLOAD FOR %v", fldManager.m_sBeginLoading)
		_, err = fldManager.m_controlSession.ExecContext (ctx, sCheckWorkload, nil)
		if err != nil { return }

		checkWorkloadEnd := "{fn teradata_values_off}CHECK WORKLOAD END"
		if ! fldManager.m_appRows.m_bIsGoverned {
			checkWorkloadEnd = "{fn teradata_failfast}" + checkWorkloadEnd // "TERADATA_FAILFAST" is only supported in TD 14.10 or higher
		}

		var rows driver.Rows
		rows, err = fldManager.m_controlSession.QueryContext (ctx, checkWorkloadEnd, nil)
		if err != nil { return }

		asColumnNames := rows.Columns ()
		dest := make ([] driver.Value, len (asColumnNames))
		rows.Next (dest)

		if len (asColumnNames) >= 2 && asColumnNames [1] != "" {
			workloadEnabled := strings.TrimSpace (dest [0].(string))

			if strings.EqualFold (workloadEnabled, "Y") {
				maxSessions := uint32 (dest [1].(int32))

				if maxSessions > 0 {
					if requestedSessions == 0 {
						permittedSessions = maxSessions
					} else {
						permittedSessions = minUint32 (requestedSessions, maxSessions)
					}

					if permittedSessions < requestedSessions {

						sWarning = fldManager.m_controlSession.makeDriverWarning (569,
							fmt.Sprintf ("Requested SESSIONS=%v was overridden by the Teradata Database as a session count of %v for statement %v",
								requestedSessions,
								permittedSessions,
								fldManager.m_sBeginLoading))

						fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)
					}

					if fldManager.m_appCon.hasTraceLog () {
						traceLog (fmt.Sprintf("Permitted FastLoad sessions count: %v", permittedSessions))
					}

					return

				} else {
					if fldManager.m_appCon.hasTraceLog () {
						traceLog ("FastLoad received no valid SESSIONS count from " + checkWorkloadEnd + ", thus assuming default SESSIONS count.")
					}
				}

			} else {
				if fldManager.m_appCon.hasTraceLog () {
					traceLog (fmt.Sprintf ("FastLoad was told to assume default SESSIONS count by %v.", checkWorkloadEnd))
				}
			}
		}
	} // end if bUseCheckWorkload

	// At this point, CHECK WORKLOAD is assumed to be unsupported, disabled, or to have returned an invalid sessions value.
	// Thus, the database system AMP count is used to determine or verify the sessions value.
	if (requestedSessions == 0) {
		permittedSessions = minUint32(DEFAULT_FASTLOAD_MAX_SESSION_COUNT, uint32(ampCnt))

	} else {
		permittedSessions = minUint32(requestedSessions, uint32(ampCnt))

		if (permittedSessions < requestedSessions) {

			sWarning = fldManager.m_controlSession.makeDriverWarning (511,
				fmt.Sprintf ("Requested SESSIONS=%v was overridden by the Teradata Database AMP limit as a session count of %v for statement %v",
					requestedSessions,
					permittedSessions,
					fldManager.m_sBeginLoading))

			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)
		}
	}

	return

} // end method getSessionsCount

func (fldManager *fastLoadManagerBase) connectFastLoad(ctx context.Context) (err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.connectFastLoad m_sTableName=%v m_bConnected=%v m_controlSession=%v m_teraCon=%v m_fastloadCon=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_controlSession, fldManager.m_teraCon, fldManager.m_fastloadCon))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.connectFastLoad m_sTableName=%v m_bConnected=%v m_controlSession=%v m_teraCon=%v m_fastloadCon=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_controlSession, fldManager.m_teraCon, fldManager.m_fastloadCon)) } ()
	}

	if fldManager.m_bConnected { return }

	defer func () {
		if err != nil {
			err = chainErrors (err, fldManager.closeFastLoad ())
		}
	} ()

	requestedSessions := fldManager.m_appRows.m_uSessions

	fldManager.m_bConnected = true // to force close of resources created below

	mapDelegatedParams := fldManager.m_appCon.m_params.getDelegatedConParams ()

	sControlParams, err := mapStringStringAsJSON (mapStringStringAddAll (mapDelegatedParams, map [string] string {
		"application_esn"  : format10Uint32 (fldManager.m_appCon.m_uSessionNumber),
		"tmode"            : "TERA",
		"connect_function" : "1", // 1=allocate LSN
	}))
	if err != nil { return }

	controlParams, err := ParseConParams(sControlParams)
	if err != nil { return }

	fldManager.m_controlSession, err = newTeradataConnection(controlParams)
	if err != nil { return }

	uDatabaseLSN, err := fldManager.m_controlSession.queryDatabaseLSN (ctx)
	if err != nil { return }

	sControlParamLSN := format10Uint32(fldManager.m_controlSession.m_uLogonSequenceNumber)

	sTeraParams, err := mapStringStringAsJSON (mapStringStringAddAll (mapDelegatedParams, map [string] string {
		"application_esn"       : format10Uint32 (fldManager.m_appCon.m_uSessionNumber),
		"control_esn"           : format10Uint32 (fldManager.m_controlSession.m_uSessionNumber),
		"database_lsn"          : format10Uint32 (uDatabaseLSN),
		"tmode"                 : "TERA",
		"connect_function"      : "2", // 2=associate LSN
		"logon_sequence_number" : sControlParamLSN,
	}))
	if err != nil { return }

	teraParams, err := ParseConParams(sTeraParams)
	if err != nil { return }

	fldManager.m_teraCon, err = newTeradataConnection(teraParams)
	if err != nil { return }

	helpSessionResult, err := executeHelpSession (fldManager.m_appCon, ctx)
	if err != nil { return }

	if getUnicodePassThroughFromHelpSessionResult (helpSessionResult) {
		if fldManager.m_appCon.hasDebugLog () { debugLog (fmt.Sprintf ("FastLoadManager.connectFastLoad enabling Unicode Pass Through m_sTableName=%v", fldManager.m_sTableName)) }
		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}SET SESSION CHARACTER SET UNICODE PASS THROUGH ON", nil)
		if err != nil { return }
	}

	permittedSessions, err := fldManager.getSessionsCount (requestedSessions, ctx, helpSessionResult)
	if err != nil { return }

	if fldManager.m_appCon.hasDebugLog () { debugLog (fmt.Sprintf ("FastLoadManager.connectFastLoad setting session DateForm m_sTableName=%v", fldManager.m_sTableName)) }
	_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}SET SESSION DateForm = IntegerDate", nil)
	if err != nil { return }

	if fldManager.m_nVectorColumnBoundVarbyte != 0 {
		if fldManager.m_appCon.hasDebugLog () { debugLog (fmt.Sprintf ("FastLoadManager.connectFastLoad m_sTableName=%v m_nVectorColumnBoundVarbyte=%v setting transform Vector_IO (for VARBYTE)", fldManager.m_sTableName, fldManager.m_nVectorColumnBoundVarbyte)) }
		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}SET TRANSFORM GROUP FOR TYPE VECTOR Vector_IO", nil)
		if err != nil { return }
	}


	if fldManager.m_nVectorColumnBoundVarchar != 0 {
		if fldManager.m_appCon.hasDebugLog () { debugLog (fmt.Sprintf ("FastLoadManager.connectFastLoad m_sTableName=%v m_nVectorColumnBoundVarchar=%v setting transform Vector_IO_VARCHAR", fldManager.m_sTableName, fldManager.m_nVectorColumnBoundVarchar)) }
		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}SET TRANSFORM GROUP FOR TYPE VECTOR Vector_IO_VARCHAR", nil)
		if err != nil { return }
	}

	sFastLoadParams, err := mapStringStringAsJSON (mapStringStringAddAll (mapDelegatedParams, map [string] string {
		"application_esn"       : format10Uint32 (fldManager.m_appCon.m_uSessionNumber),
		"control_esn"           : format10Uint32 (fldManager.m_controlSession.m_uSessionNumber),
		"database_lsn"          : format10Uint32 (uDatabaseLSN),
		"partition"             : "fastload",
		"connect_function"      : "2", // 2=associate LSN
		"logon_sequence_number" : sControlParamLSN,
	}))
	if err != nil { return }

	fastloadParams, err := ParseConParams(sFastLoadParams)
	if err != nil { return }

	fldManager.m_fastloadCon = make([]*TeradataConnection, permittedSessions)
	for i := 0; i < len(fldManager.m_fastloadCon); i++ {
		fldManager.m_fastloadCon[i], err = newTeradataConnection(fastloadParams)
		if err != nil { return }
	}

	return

} // end method connectFastLoad

func (fldManager *fastLoadManagerBase) closeFastLoad() (err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.closeFastLoad m_sTableName=%v m_bConnected=%v m_controlSession=%v m_teraCon=%v m_fastloadCon=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_controlSession, fldManager.m_teraCon, fldManager.m_fastloadCon))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.closeFastLoad m_sTableName=%v m_bConnected=%v m_controlSession=%v m_teraCon=%v m_fastloadCon=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_controlSession, fldManager.m_teraCon, fldManager.m_fastloadCon)) } ()
	}

	if fldManager.m_bConnected {
		defer func () {
			fldManager.m_bConnected = false
			fldManager.m_teraCon = nil
			fldManager.m_fastloadCon = nil
			fldManager.m_controlSession = nil
		} ()

		if fldManager.m_teraCon != nil {
			err = chainErrors(err, fldManager.m_teraCon.Close())
		}

		if fldManager.m_fastloadCon != nil {
			for i := 0; i < len(fldManager.m_fastloadCon); i++ {
				if fldManager.m_fastloadCon[i] != nil {
					err = chainErrors(err, fldManager.m_fastloadCon[i].Close())
				}
			}
		}

		if fldManager.m_controlSession != nil {
			err = chainErrors(err, fldManager.m_controlSession.Close())
		}
	}

	return

} // end method closeFastLoad

func (fldManager *fastLoadManagerBase) retryExecuteCreateOrDrop (con *TeradataConnection, ddl string, ctx context.Context) (err error) {

	for i := 1; i <= 5; i++ {
		_, err = con.ExecContext (ctx, ddl, nil)
		if err == nil { break }

		errCode := GetErrorCode(err)
		if errCode == 2631 { // Transaction ABORTed due to %VSTR.
			if fldManager.m_appCon.hasDebugLog () {
				debugLog(fmt.Sprintf("FastLoadManager.retryExecuteCreateOrDrop ddl=%v is ignoring retryable error %v. Now sleeping for 5 seconds to allow error condition to clear...", ddl, errCode))
			}
			threadSleep(fldManager.m_appCon.hasTimingLog(), time.Second * 5)
		} else {
			break
		}
	}

	return

} // end method retryExecuteCreateOrDrop

func (fldManager *fastLoadManagerBase) executeCreateOrDrop(con *TeradataConnection, ddl string, ctx context.Context) (err error) {

	var ignoreError string

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.executeCreateOrDrop ddl=%v", ddl))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.executeCreateOrDrop ddl=%v%v", ddl, ignoreError)) } ()
	}

	err = fldManager.retryExecuteCreateOrDrop(con, ddl, ctx)
	if err != nil {
		errCode := GetErrorCode(err)
		if errCode == 3807 { // Object '%VSTR' does not exist.
			ignoreError = fmt.Sprintf(" ignoring error %v", errCode)
			err = nil
		}
	}

	return

} // end method executeCreateOrDrop

func (fldManager *fastLoadManagerBase) dropFastLoadErrorTables(ctx context.Context) (err error) {

	err = fldManager.executeCreateOrDrop(fldManager.m_controlSession, "DROP TABLE " + fldManager.m_sTableNameErr1, ctx)
	if err != nil { return }

	return fldManager.executeCreateOrDrop(fldManager.m_controlSession, "DROP TABLE " + fldManager.m_sTableNameErr2, ctx)

} // end method dropFastLoadErrorTables

func (fldManager *fastLoadManagerBase) verifyFastLoadErrorTable1RowCount (uExpectedRowCount uint64, uFirstRowNumber uint64, ctx context.Context) (err error) {

	uActualRowCount := uint64(0)

	sQuery := "{fn teradata_values_off}LOCKING " + fldManager.m_sTableNameErr1 + " FOR ACCESS " +
		"SELECT CAST(COUNT(*) AS BIGINT) FROM " + fldManager.m_sTableNameErr1 +
		" WHERE CAST(SUBSTRING(DataParcel FROM BYTES(DataParcel) - 3 FOR 4) AS BYTE(4)) >= '" + fmt.Sprintf("%0*x", 8, uFirstRowNumber) + "'xb" ;

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.verifyFastLoadErrorTable1RowCount m_uErrorQueryCount=%v m_uErrorQueryInterval=%v uExpectedRowCount=%v uFirstRowNumber=%v sQuery=%v",
			fldManager.m_appRows.m_uErrorQueryCount, fldManager.m_appRows.m_uErrorQueryInterval, uExpectedRowCount, uFirstRowNumber, sQuery))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.verifyFastLoadErrorTable1RowCount m_sTableNameErr1=%v uExpectedRowCount=%v uActualRowCount=%v",
			fldManager.m_sTableNameErr1, uExpectedRowCount, uActualRowCount)) } ()
	}

	for uAttempt := uint32(1) ; uActualRowCount != uExpectedRowCount && uAttempt <= fldManager.m_appRows.m_uErrorQueryCount ; uAttempt++ {
		if uAttempt > 1 {
			time.Sleep(time.Millisecond * time.Duration(fldManager.m_appRows.m_uErrorQueryInterval))
		}

		if fldManager.m_appCon.hasDebugLog () {
			debugLog(fmt.Sprintf("FastLoadManager.verifyFastLoadErrorTable1RowCount m_sTableNameErr1=%v uAttempt=%v", fldManager.m_sTableNameErr1, uAttempt))
		}

		rows, err := fldManager.m_teraCon.QueryContext (ctx, sQuery, nil)
		if err != nil { return err }

		dest := make([]driver.Value, 1)
		for {
			err = rows.Next(dest)
			if err == nil {
				uActualRowCount = uint64 (dest [0].(int64))
			} else if errors.Is (err, io.EOF) {
				err = rows.Close()
				if err != nil { return err }
				break
			} else {
				err = chainErrors(err, rows.Close())
				return err
			}
		} // end for
	} // end for uAttempt

	if uActualRowCount != uExpectedRowCount {

		return fldManager.m_teraCon.makeDriverError (nil, 517,
			fmt.Sprintf ("Expected row count %v but obtained row count %v from FastLoad error table %v",
				uExpectedRowCount,
				uActualRowCount,
				fldManager.m_sTableNameErr2))
	}

	return

} // end method verifyFastLoadErrorTable1RowCount

func (fldManager *fastLoadManagerBase) selectFastLoadErrorTable1Rows (numRowsToSend uint64, numRowsSent uint64, uFirstRowNumber uint64, ctx context.Context) (err error) {

	var asErrors []string

	sQuery := "{fn teradata_values_off}LOCKING " + fldManager.m_sTableNameErr1 + " FOR ACCESS" +
		" SELECT ErrorCode" +
		", ErrorFieldName" +
		", CAST(SUBSTRING(DataParcel FROM BYTES(DataParcel) - 3 FOR 4) AS BYTE(4)) AS RowNumber" +
		" FROM " + fldManager.m_sTableNameErr1 +
		" WHERE RowNumber >= '" + fmt.Sprintf("%0*x", 8, uFirstRowNumber) + "'xb" +
		" ORDER BY RowNumber"

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.selectFastLoadErrorTable1Rows m_sTableNameErr1=%v m_bBatchInsert=%v numRowsToSend=%v numRowsSent=%v uFirstRowNumber=%v sQuery=%v",
			fldManager.m_sTableNameErr1, fldManager.m_bBatchInsert, numRowsToSend, numRowsSent, uFirstRowNumber, sQuery))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.selectFastLoadErrorTable1Rows m_sTableNameErr1=%v asErrors[:%v]=%v", fldManager.m_sTableNameErr1,
			minInt(len(asErrors), 10), func ()(string) {
				var sError string
				for i := 0; i < minInt(len(asErrors), 10); i++ {
					sError += "\n" + asErrors[i]
				}
				return sError
			} () ))
		} ()
	}

	rows, err := fldManager.m_teraCon.QueryContext (ctx, sQuery, nil)
	if err != nil { return err }

	asColumnNames := rows.Columns()
	dest := make([]driver.Value, len(asColumnNames))
	for {
		err = rows.Next(dest)
		if err == nil {
			errCode := dest [0].(int32)

			colName := func () (string) { if dest [1] == nil { return "F_" } ; return dest [1].(string) } ()
			colName = doubleQuote(colName[2:len(colName)]) // steps past "F_" prepended to every target table column name

			rowNum := uint64 (binary.BigEndian.Uint32 (dest [2].([] byte)))
			rowNum = rowNum - uFirstRowNumber + 1

			var dataError error
			if fldManager.m_bBatchInsert {
				dataError = fldManager.m_teraCon.formatDatabaseError(nil, uint16(errCode),
					fmt.Sprintf("FastLoad failed to insert %v of %v batched rows. Batched row %v failed to insert because of Teradata Database error %v in %v",
					numRowsToSend - numRowsSent, numRowsToSend, rowNum, errCode, (fldManager.m_sTableName+"."+colName)))
			} else {
				dataError = fldManager.m_teraCon.formatDatabaseError(nil, uint16(errCode),
					fmt.Sprintf("FastLoad failed to insert row because of Teradata Database error %v in %v", errCode, (fldManager.m_sTableName+"."+colName)))
			}
			asErrors = append(asErrors, dataError.Error())
		} else if errors.Is (err, io.EOF) {
			err = rows.Close()
			if err != nil { return err }
			break
		} else {
			err = chainErrors(err, rows.Close())
			return err
		}
	} // end for

	fldManager.m_appCon.m_mapRequestToErrors [fldManager.m_appRows.m_sNativeSQL] = asErrors
	return err

} // end method selectFastLoadErrorTable1Rows

func (fldManager *fastLoadManagerBase) selectFastLoadErrorTable2(ctx context.Context) (err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.selectFastLoadErrorTable2 m_sTableNameErr2=%v", fldManager.m_sTableNameErr2))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.selectFastLoadErrorTable2 m_sTableNameErr2=%v", fldManager.m_sTableNameErr2)) } ()
	}

	rowCount, err := fldManager.getFastLoadErrorTable2RowCount(ctx)
	if err != nil { return }

	if rowCount != 0 {
		err = chainErrors(err, fldManager.selectFastLoadErrorTable2Rows(rowCount, ctx))
	}

	return

} // end method selectFastLoadErrorTable2

func (fldManager *fastLoadManagerBase) getFastLoadErrorTable2RowCount (ctx context.Context) (rowCount int64, err error) {

	rowCount = -1
	sQuery := "{fn teradata_values_off}LOCKING " + fldManager.m_sTableNameErr2 + " FOR ACCESS SELECT CAST(COUNT(*) AS BIGINT) FROM " + fldManager.m_sTableNameErr2

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.getFastLoadErrorTable2RowCount sQuery=%v", sQuery))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.getFastLoadErrorTable2RowCount m_sTableNameErr2=%v rowCount=%v", fldManager.m_sTableNameErr2, rowCount)) } ()
	}

	rows, err := fldManager.m_controlSession.QueryContext (ctx, sQuery, nil)
	if err != nil { return }

	dest := make([]driver.Value, 1)
	for {
		err = rows.Next(dest)
		if err == nil {
			rowCount = dest [0].(int64)
		} else if errors.Is (err, io.EOF) {
			err = rows.Close()
			if err != nil { return rowCount, err }
			return rowCount, nil
		} else {
			err = chainErrors(err, rows.Close())
			return rowCount, err
		}
	} // end for

} // end method getFastLoadErrorTable2RowCount

func (fldManager *fastLoadManagerBase) selectFastLoadErrorTable2Rows (rowCount int64, ctx context.Context) (err error) {

	var asErrors []string

	sQuery := "{fn teradata_values_off}LOCKING " + fldManager.m_sTableNameErr2 + " FOR ACCESS SELECT * FROM " + fldManager.m_sTableNameErr2

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.selectFastLoadErrorTable2Rows m_sTableNameErr2=%v rowCount=%v sQuery=%v",
			fldManager.m_sTableNameErr2, rowCount, sQuery))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.selectFastLoadErrorTable2Rows m_sTableNameErr2=%v asErrors[:%v]=%v",
			fldManager.m_sTableNameErr2,
			minInt(len(asErrors), 10), func ()(string) {
				var sError string
				for i := 0; i < minInt(len(asErrors), 10); i++ {
					sError += "\n" + asErrors[i]
				}
				return sError
			} () ))
		} ()
	}

	rows, err := fldManager.m_controlSession.QueryContext (ctx, sQuery, nil)
	if err != nil { return }

	asColumnNames := rows.Columns()
	dest := make([]driver.Value, len(asColumnNames))

	for i := 1; i <= MAX_FASTLOAD_ERROR_TABLE_ROW_COUNT; i++ {

		err = rows.Next(dest)

		if err == nil {
			msg := ""
			bByteArray := false

			for j := 0; j < len(dest); j++ {

				if  dest [j] != nil && reflect.TypeOf( dest [j]).String() == "[]uint8" {
					ba :=  dest [j].([]uint8)
					balen := func ()(int) { if len(ba) < MAX_FASTLOAD_ERROR_TABLE_ARRAY_LENGTH { return len(ba) } ; return MAX_FASTLOAD_ERROR_TABLE_ARRAY_LENGTH } ()
					msg += func ()(string) { if bByteArray { return "" /*hex.Dump appends a newline*/ } ; return "\n" } () +
						asColumnNames[j] + fmt.Sprintf(": byte array length=%v bytes, dump length=%v bytes\n", len(ba), balen) + hex.Dump(ba[:balen])
					bByteArray = true

				} else {
					str := fmt.Sprintf("%v",  dest [j])
					strlen := func ()(int) { if len(str) < MAX_FASTLOAD_ERROR_TABLE_ARRAY_LENGTH { return len(str) } ; return MAX_FASTLOAD_ERROR_TABLE_ARRAY_LENGTH } ()
					truncationStr := ""
					if ((dest [j] != nil) && (strlen != 0) && (len(str) > MAX_FASTLOAD_ERROR_TABLE_ARRAY_LENGTH)) {
						truncationStr = fmt.Sprintf(" (only showing string length %v of %v)", strlen, len(str))
					}
					msg += func ()(string) { if bByteArray { return "" /*hex.Dump appends a newline*/ } ; return "\n" } () +
						asColumnNames[j] + "=" + str[0:strlen] + truncationStr
					bByteArray = false
				}
			} // end for j

			errMsg := fmt.Sprintf("A row count of %v was found in FastLoad table %v. A row count of 0 was expected. Row %v has Unique Primary Index violation for data: %v",
				rowCount,
				fldManager.m_sTableNameErr2,
				i,
				msg)

			sError := fldManager.m_controlSession.makeDriverError (nil, 519, errMsg)
			asErrors = append(asErrors, sError.Error())

		} else if errors.Is (err, io.EOF) {
			err = rows.Close()
			if err != nil { return }
			fldManager.m_appCon.m_mapRequestToErrors [fldManager.m_appRows.m_sNativeSQL] = asErrors
			return

		} else {
			err = chainErrors(err, rows.Close())
			return
		}
	} // end for i

	return

} // end method selectFastLoadErrorTable2Rows

func (fldManager *fastLoadManagerBase) abortFastLoad (ctx context.Context) (err error) {

	fastloadTableLocked := false

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.abortFastLoad m_sTableName=%v m_bConnected=%v m_bFastloading=%v m_bCheckFastloadErrorTable2=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_bFastloading, fldManager.m_bCheckFastloadErrorTable2))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.abortFastLoad m_sTableName=%v fastloadTableLocked=%v", fldManager.m_sTableName, fastloadTableLocked)) } ()
	}

	if fldManager.m_bConnected {

		if !fldManager.m_bFastloading { // just in case a previous FastLoad left the database table locked (e.g. caused by the standalone FastLoad utility)
			_, err = fldManager.m_controlSession.QueryContext (ctx, "SELECT 1 FROM "+fldManager.m_sTableName+" WHERE 1=2", nil)
			if err != nil {
				if GetErrorCode(err) == 2652 { // Operation not allowed: %DBID.%TVMID is being Loaded.
					fastloadTableLocked = true
					err = nil
				} else {
					return
				}
			}
		} else {
			err = fldManager.closeFastLoad()
			if err != nil { return }

			err = fldManager.connectFastLoad(ctx)
			if err != nil { return }
		}

		var errSave error
		if fldManager.m_bFastloading || fastloadTableLocked {
			_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_nativesql}{fn teradata_autocommit_on}", nil)
			if err != nil { return }

			// calling ExecContext here because we don't want to deserialize HUTConfig out of Record parcel
			_, err = fldManager.m_controlSession.ExecContext (ctx, fldManager.m_sBeginLoading, nil)
			if err != nil { return }

			_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_nativesql}{fn teradata_autocommit_off}", nil)
			if err != nil { return }

			_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}END LOADING", nil)
			if err != nil { return }

			_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_commit}", nil)
			if err != nil { return }

			_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_nativesql}{fn teradata_autocommit_on}", nil)
			if err != nil { return }

			if fldManager.m_bCheckFastloadErrorTable2 && !fastloadTableLocked {
				errSave = fldManager.selectFastLoadErrorTable2(ctx)
			}

			_, err := fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}DELETE " + fldManager.m_sTableName + " ALL", nil)
			if err != nil { return chainErrors(errSave, err) }
		}

		return chainErrors(errSave, fldManager.dropFastLoadErrorTables(ctx))
	}

	return

} // end method abortFastLoad

func (fldManager *fastLoadManagerBase) beginFastLoad (ctx context.Context) (err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.beginFastLoad m_bConnected=%v m_bFastloading=%v m_sBeginLoading=%v",
			fldManager.m_bConnected, fldManager.m_bFastloading, fldManager.m_sBeginLoading))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.beginFastLoad m_sTableName=%v m_bConnected=%v m_bFastloading=%v m_bCheckFastloadErrorTable2=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_bFastloading, fldManager.m_bCheckFastloadErrorTable2)) } ()
	}

	if fldManager.m_bConnected && !fldManager.m_bFastloading {
		defer func () {
			if err != nil {
				err = chainErrors(err, fldManager.abortFastLoad(ctx))
				err = chainErrors(err, fldManager.closeFastLoad())
			}
		} ()

		err = fldManager.abortFastLoad(ctx)
		if err != nil { return }

		// calling ExecContext here because we don't want to deserialize HUTConfig out of Record parcel
		_, err = fldManager.m_controlSession.ExecContext (ctx, fldManager.m_sBeginLoading, nil)
		if err != nil { return }

		fldManager.m_bFastloading = true

		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_nativesql}{fn teradata_autocommit_off}", nil)
		if err != nil { return }

		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}"+fldManager.m_sUsingInsertValues, nil)
		if err != nil { return }

		fldManager.m_bCheckFastloadErrorTable2 = true
	}

	return

} // end method beginFastLoad

func (fldManager *fastLoadManagerBase) getErrorCount () int {

	return len (fldManager.m_appCon.m_mapRequestToErrors [fldManager.m_appRows.m_sNativeSQL]) // length of nil slice is zero

} // end getErrorCount

func (fldManager *fastLoadManagerBase) endFastLoad (ctx context.Context) (err error) {

	var sWarning string

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.endFastLoad m_sTableName=%v m_bConnected=%v m_bFastloading=%v m_uNumTotalRowsSent=%v getErrorCount=%v len(m_asWarnings)=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_bFastloading, fldManager.m_uNumTotalRowsSent, fldManager.getErrorCount (), len(fldManager.m_asWarnings)))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.endFastLoad m_sTableName=%v m_bConnected=%v m_bFastloading=%v getErrorCount=%v len(m_asWarnings)=%v sWarning=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_bFastloading, fldManager.getErrorCount (), len(fldManager.m_asWarnings), sWarning)) } ()
	}

	if fldManager.m_bConnected && fldManager.m_bFastloading {
		defer func () {
			defer func () {
				fldManager.m_bFastloading = false
				fldManager.m_uNumTotalRowsSent = 0
				fldManager.m_nCurrentRowNumber = 0
				fldManager.m_bCheckFastloadErrorTable2 = false
			} ()
			if err != nil {
				err = chainErrors(err, fldManager.abortFastLoad(ctx))
			}
		} ()

		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}CHECKPOINT LOADING END", nil)
		if err != nil { return err }

		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_commit}", nil)
		if err != nil { return err }

		resControlSession, err := fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_rpo(E)}END LOADING", nil)
		if err != nil { return err }

		rowsAffected, err := resControlSession.RowsAffected()
		if err != nil { return err }

		if uint64(rowsAffected) != fldManager.m_uNumTotalRowsSent {

			sWarning = fldManager.m_controlSession.makeDriverWarning (518,
				fmt.Sprintf ("Found %v duplicate or faulty row(s) while ending FastLoad of database table %v: expected a row count of %v, got a row count of %v",
					fldManager.m_uNumTotalRowsSent - uint64 (rowsAffected),
					fldManager.m_sTableName,
					fldManager.m_uNumTotalRowsSent,
					rowsAffected))

			fldManager.m_asWarnings = append(fldManager.m_asWarnings, sWarning)
		}

		_, err = fldManager.m_controlSession.ExecContext (ctx, "{fn teradata_commit}", nil)
		if err != nil { return err }

		_, err = fldManager.m_controlSession.ExecContext (ctx,  "{fn teradata_nativesql}{fn teradata_autocommit_on}", nil)
		if err != nil { return err }

		var errSave error
		if fldManager.m_appRows.m_bManageErrorTables {

			errSave = fldManager.selectFastLoadErrorTable2(ctx)

			err = fldManager.dropFastLoadErrorTables(ctx)
			if err != nil { return chainErrors(errSave, err) }
		}

		err = fldManager.closeFastLoad()
		if err != nil { return chainErrors(errSave, err) }

		return errSave
	}

	return

} // end method endFastLoad

func (fldManager *fastLoadManagerBase) rollbackFastLoad(ctx context.Context) (err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.rollbackFastLoad m_sTableName=%v m_bConnected=%v m_bFastloading=%v m_uNumTotalRowsSent=%v m_bCheckFastloadErrorTable2=%v getErrorCount=%v len(m_asWarnings)=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_bFastloading, fldManager.m_uNumTotalRowsSent, fldManager.m_bCheckFastloadErrorTable2, fldManager.getErrorCount (), len(fldManager.m_asWarnings)))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.rollbackFastLoad m_sTableName=%v m_bConnected=%v m_bFastloading=%v getErrorCount=%v len(m_asWarnings)=%v",
			fldManager.m_sTableName, fldManager.m_bConnected, fldManager.m_bFastloading, fldManager.getErrorCount (), len(fldManager.m_asWarnings))) } ()
	}

	if fldManager.m_bConnected && fldManager.m_bFastloading {
		defer func () {
			defer func () {
				fldManager.m_bFastloading = false
				fldManager.m_uNumTotalRowsSent = 0
				fldManager.m_nCurrentRowNumber = 0
				fldManager.m_bCheckFastloadErrorTable2 = false
			} ()
		} ()

		err = fldManager.abortFastLoad(ctx)
		if err != nil { return }

		err = fldManager.closeFastLoad()
		if err != nil { return }
	}

	return

} // end method rollbackFastLoad

func (fldManager *fastLoadManagerBase) executeInsert (activityCount *uint64, aBindValues [] driver.NamedValue, ctx context.Context) (err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.executeInsert m_sTableName=%v", fldManager.m_sTableName))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.executeInsert m_sTableName=%v err=%v", fldManager.m_sTableName, err)) } ()
	}

	var numRowsToSend uint64
	var uFirstRowNumber uint64
	var numRowsSent uint64

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.executeInsert m_sTableName=%v m_uNumTotalRowsSent=%v getErrorCount=%v len(m_asWarnings)=%v %v",
			fldManager.m_sTableName, fldManager.m_uNumTotalRowsSent, fldManager.getErrorCount (), len(fldManager.m_asWarnings), fldManager))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.executeInsert m_sTableName=%v m_bAlreadyAutoCommitted=%v m_bBatchInsert=%v numRowsToSend=%v uFirstRowNumber=%v numRowsSent=%v m_uNumTotalRowsSent=%v getErrorCount=%v len(m_asWarnings)=%v %v",
			fldManager.m_sTableName, fldManager.m_bAlreadyAutoCommitted, fldManager.m_bBatchInsert, numRowsToSend, uFirstRowNumber, numRowsSent, fldManager.m_uNumTotalRowsSent, fldManager.getErrorCount (), len(fldManager.m_asWarnings), fldManager)) } ()
	}

	if fldManager.m_appCon.m_bAutoCommit {
		fldManager.m_bSaveErrorsWarnings = true // save errors and warnings
	}

	if len (aBindValues) == 0 {
		return fldManager.m_appCon.makeDriverError (nil, 512, "No bound parameter values specified")
	}

	fldManager.m_bBatchInsert = func ()(bool) { switch aBindValues[0].Value.(type) { case [][] any: return true ; default: return false } } ()
	numRowsToSend = uint64(func ()(int) { if fldManager.m_bBatchInsert { return len(aBindValues[0].Value.([][] any)) } ; return 1 } ())
	uFirstRowNumber = uint64(fldManager.m_nCurrentRowNumber + 1)

	if fldManager.m_bBatchInsert && numRowsToSend == 0 {
		return fldManager.m_appCon.makeDriverError (nil, 500, "Empty batch contains no rows")
	}

	err = fldManager.connectFastLoad(ctx)
	if err != nil { return }

	aBindValuesInternal, err := fldManager.distributeRows(aBindValues, numRowsToSend, uFirstRowNumber)
	if err != nil || len(fldManager.m_asWarningsAtTypeCast) != 0 { return }

	err = fldManager.beginFastLoad(ctx)
	if err != nil { return }

	for {

		for i := 0; i < len(fldManager.m_fastloadCon); i++ {
			if aBindValuesInternal[i] != nil {
				_, err := fldManager.m_fastloadCon[i].ExecContext (ctx, "{fn teradata_provide(request_scope_send_only)}", aBindValuesInternal[i])
				if err != nil { return err }
			}
		}

		for i := 0; i < len(fldManager.m_fastloadCon); i++ {
			if aBindValuesInternal[i] != nil {
				resFastLoadCon, err := fldManager.m_fastloadCon[i].ExecContext (ctx, "{fn teradata_provide(request_scope_receive_only)}", nil)
				if err != nil { return err }

				rowsAffected, err := resFastLoadCon.RowsAffected()
				if err != nil { return err }

				numRowsSent += uint64(rowsAffected)
			}
		}

		for i := 0; i < len(fldManager.m_fastloadCon); i++ {
			if aBindValuesInternal[i] != nil && fldManager.m_fastloadCon[i].m_nFastLoadCurrentRow > 0 {
				if fldManager.m_fastloadCon[i].m_nFastLoadCurrentRow > len(aBindValuesInternal[i][0].Value.([][]driver.NamedValue)) {
					aBindValuesInternal[i][0].Value = aBindValuesInternal[i][0].Value.([][]driver.NamedValue)[0:]
				} else {
					aBindValuesInternal[i][0].Value = aBindValuesInternal[i][0].Value.([][]driver.NamedValue)[fldManager.m_fastloadCon[i].m_nFastLoadCurrentRow : ]
				}
			} else {
				aBindValuesInternal[i] = nil
			}
		}

		bBreak := true
		for i := 0; i < len(fldManager.m_fastloadCon); i++ {
			if aBindValuesInternal[i] != nil {
				bBreak = false
				break
			}
		}
		if bBreak { break }

	}

	var errSave error
	if numRowsToSend != numRowsSent && fldManager.m_appRows.m_bManageErrorTables {
		errSave = fldManager.verifyFastLoadErrorTable1RowCount(numRowsToSend - numRowsSent, uFirstRowNumber, ctx)
		if errSave == nil {
			errSave = fldManager.selectFastLoadErrorTable1Rows(numRowsToSend, numRowsSent, uFirstRowNumber, ctx)
		}
	}

	fldManager.m_uNumTotalRowsSent += numRowsSent
	*activityCount = numRowsSent

	if fldManager.m_appCon.m_bAutoCommit {
		fldManager.m_bAlreadyAutoCommitted = true
		err = fldManager.endFastLoad(ctx)
		if err != nil { return chainErrors(errSave, err) }
	}

	return errSave

} // end method executeInsert

func (fldManager *fastLoadManagerBase) distributeRows(aBindValues []driver.NamedValue, numRowsToSend uint64, uFirstRowNumber uint64) (aBindValuesInternal [][]driver.NamedValue, err error) {

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.distributeRows m_sTableName=%v numRowsToSend=%v uFirstRowNumber=%v", fldManager.m_sTableName, numRowsToSend, uFirstRowNumber))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.distributeRows m_sTableName=%v err=%v", fldManager.m_sTableName, err)) } ()
	}

	aBindValuesInternal = make([][]driver.NamedValue, len(fldManager.m_fastloadCon))
	numRowsInFastLoadCon := make([]int, len(fldManager.m_fastloadCon))
	numExpectedBoundParameterValues := len(fldManager.m_preparedRows.m_aParamMetadata)
	var numActualBoundParameterValues int
	var numFastloadConsToBeUsed int

	if fldManager.m_appCon.hasTraceLog () {
		traceLog(fmt.Sprintf("> enter FastLoadManager.distributeRows m_sTableName=%v m_bBatchInsert=%v numExpectedBoundParameterValues=%v len(m_fastloadCon)=%v numRowsToSend=%v uFirstRowNumber=%v",
			fldManager.m_sTableName, fldManager.m_bBatchInsert, numExpectedBoundParameterValues, len(fldManager.m_fastloadCon), numRowsToSend, uFirstRowNumber))
		defer func () { traceLog(fmt.Sprintf("< leave FastLoadManager.distributeRows m_sTableName=%v numActualBoundParameterValues=%v numFastloadConsToBeUsed=%v numRowsInFastLoadCon=%v",
			fldManager.m_sTableName, numActualBoundParameterValues, numFastloadConsToBeUsed, numRowsInFastLoadCon)) } ()
	}

	if fldManager.m_bBatchInsert {
		fldManager.m_preparedRows.m_bSendSIP = false // force intervals, date, times and timestamps to convert to VARCHAR

		fldManager.m_aBindMetadata, err = fldManager.m_preparedRows.validateBatchValues(aBindValues)
		if err != nil { return nil, err }

		if fldManager.m_appCon.hasDebugLog () {
			for i := range fldManager.m_aBindMetadata {
				debugLog(fmt.Sprintf("FastLoadManager.distributeRows m_sTableName=%v m_aBindMetadata[%v]=%+v", fldManager.m_sTableName, i, fldManager.m_aBindMetadata[i]))
			}
		}

		aaBatchValues := aBindValues[0].Value.([][]driver.NamedValue)

		for i := 0; i < len(aaBatchValues); i++ {

			numActualBoundParameterValues = len(aaBatchValues[i])

			if numExpectedBoundParameterValues != numActualBoundParameterValues {

				return nil, fldManager.m_controlSession.makeDriverError (nil, 513,
					fmt.Sprintf ("Batched row %v actual bound parameter count %v differs from expected bound parameter count %v",
						i + 1,
						numActualBoundParameterValues,
						numExpectedBoundParameterValues))
			}

			if i == 0 {
				if fldManager.m_fastloadCon[0].m_fastloadBindMetadata != nil {

					for j := range fldManager.m_fastloadCon[0].m_fastloadBindMetadata {

						actualCookedDataType   := fldManager.m_aBindMetadata[j].m_uCookedDataType
						expectedCookedDataType := fldManager.m_fastloadCon[0].m_fastloadBindMetadata[j].m_uCookedDataType

						if actualCookedDataType != expectedCookedDataType {

							return nil, fldManager.m_controlSession.makeDriverError (nil, 515,
								fmt.Sprintf ("Bound parameter %v type %v (%v) differs from expected type %v (%v)",
									j + 1,
									fldManager.getTeradataTypeName (actualCookedDataType),
									actualCookedDataType,
									fldManager.getTeradataTypeName (expectedCookedDataType),
									expectedCookedDataType))
						}
					}
				} else {
					for j := range fldManager.m_fastloadCon {
						fldManager.m_fastloadCon[j].m_fastloadBindMetadata = fldManager.m_aBindMetadata
					}

					fldManager.m_sUsingInsertValues, err = fldManager.getUsingInsertValues (aBindValues)
					if err != nil {
						err = chainErrors(err, fldManager.closeFastLoad())
						return
					}

					if len(fldManager.m_asWarningsAtTypeCast) != 0 {
						for j := range fldManager.m_asWarningsAtTypeCast {
							fldManager.m_asWarnings = append(fldManager.m_asWarnings, fldManager.m_asWarningsAtTypeCast[j])
						}
						err = fldManager.closeFastLoad()
						return
					}
				}
			}

			if aBindValuesInternal[fldManager.m_nFastLoadConIndex] == nil {
				aBindValuesInternal[fldManager.m_nFastLoadConIndex] = make([]driver.NamedValue, 1)
				aaBatchValuesInternal := make([][]driver.NamedValue, 1)
				copy(aaBatchValuesInternal, aaBatchValues[i:(i+1)])
				aBindValuesInternal[fldManager.m_nFastLoadConIndex][0] = driver.NamedValue{Ordinal:1, Value:aaBatchValuesInternal}
			} else {
				aaBatchValuesInternal := aBindValuesInternal[fldManager.m_nFastLoadConIndex][0].Value.([][]driver.NamedValue)
				aaBatchValuesInternal = append(aaBatchValuesInternal, aaBatchValues[i:(i+1)]...)
				aBindValuesInternal[fldManager.m_nFastLoadConIndex][0].Value = aaBatchValuesInternal
			}

			aaBatchValuesInternal := aBindValuesInternal[fldManager.m_nFastLoadConIndex][0].Value.([][]driver.NamedValue)
			idx := len(aaBatchValuesInternal)-1
			fldManager.m_nCurrentRowNumber++
			aaBatchValuesInternal[idx] = append(aaBatchValuesInternal[idx],
				driver.NamedValue{Ordinal:(len(aaBatchValuesInternal[idx]) + 1), Value:NewTeradataValueInteger(fldManager.m_nCurrentRowNumber)})

			if fldManager.m_appCon.hasDebugLog () {
				for j := 0; j < len(aaBatchValuesInternal[idx]); j++ {
					var metadata string
					if j < len(fldManager.m_aBindMetadata) {
						metadata = fmt.Sprintf("m_aBindMetadata[%v]=%v", j, fldManager.m_aBindMetadata[j])
					} else {
						metadata = "appended RowNumber"
					}
					str := fmt.Sprintf("%v", aaBatchValuesInternal[idx][j])
					strlen := int(math.Min(float64(50), float64(len(str))))
					debugLog(fmt.Sprintf("FastLoadManager.distributeRows m_sTableName=%v m_nFastLoadConIndex=%v %v %T%v aaBatchValuesInternal[%v][%v]=%T%v (len=%v)",
						fldManager.m_sTableName, fldManager.m_nFastLoadConIndex, metadata, aaBatchValuesInternal[idx][j].Value,
						fldManager.getTeradataValueTypeName(aaBatchValuesInternal[idx][j].Value), idx, j, aaBatchValuesInternal[idx][j], str[:strlen], len(str)))
				}
			}

			numRowsInFastLoadCon[fldManager.m_nFastLoadConIndex]++
			fldManager.m_nFastLoadConIndex++
			if fldManager.m_nFastLoadConIndex >= len(fldManager.m_fastloadCon) {
				fldManager.m_nFastLoadConIndex = 0
			}
		}
	} else { // !fldManager.m_bBatchInsert
		fldManager.m_preparedRows.m_bSendSIP = false // force intervals, date, times and timestamps to convert to VARCHAR

		fldManager.m_aBindMetadata, err = fldManager.m_preparedRows.validateBindValues(aBindValues)
		if err != nil { return nil, err }

		if fldManager.m_appCon.hasDebugLog () {
			for i := range fldManager.m_aBindMetadata {
				debugLog(fmt.Sprintf("FastLoadManager.distributeRows m_sTableName=%v m_aBindMetadata[%v]=%v", fldManager.m_sTableName, i, fldManager.m_aBindMetadata[i]))
			}
		}

		numActualBoundParameterValues = len(aBindValues)

		if numExpectedBoundParameterValues != numActualBoundParameterValues {

			return nil, fldManager.m_controlSession.makeDriverError (nil, 514,
				fmt.Sprintf ("Actual bound parameter count %v differs from expected bound parameter count %v",
					numActualBoundParameterValues,
					numExpectedBoundParameterValues))
		}

		if fldManager.m_fastloadCon[0].m_fastloadBindMetadata != nil {
			for j := range fldManager.m_fastloadCon[0].m_fastloadBindMetadata {

				actualCookedDataType   := fldManager.m_aBindMetadata[j].m_uCookedDataType
				expectedCookedDataType := fldManager.m_fastloadCon[0].m_fastloadBindMetadata[j].m_uCookedDataType

				if actualCookedDataType != expectedCookedDataType {

					return nil, fldManager.m_controlSession.makeDriverError (nil, 515,
						fmt.Sprintf ("Bound parameter %v type %v (%v) differs from expected type %v (%v)",
							j + 1,
							fldManager.getTeradataTypeName (actualCookedDataType),
							actualCookedDataType,
							fldManager.getTeradataTypeName (expectedCookedDataType),
							expectedCookedDataType))
				}
			}
		} else {
			for j := range fldManager.m_fastloadCon {
				fldManager.m_fastloadCon[j].m_fastloadBindMetadata = fldManager.m_aBindMetadata
			}

			fldManager.m_sUsingInsertValues, err = fldManager.getUsingInsertValues (aBindValues)
			if err != nil {
				err = chainErrors(err, fldManager.closeFastLoad())
				return
			}

			if len(fldManager.m_asWarningsAtTypeCast) != 0 {
				for j := range fldManager.m_asWarningsAtTypeCast {
					fldManager.m_asWarnings = append(fldManager.m_asWarnings, fldManager.m_asWarningsAtTypeCast[j])
				}
				err = fldManager.closeFastLoad()
				return
			}
		}
		aBindValuesInternal[fldManager.m_nFastLoadConIndex] = make([]driver.NamedValue, numExpectedBoundParameterValues)
		for i := 0; i < len(aBindValues); i++ {
			aBindValuesInternal[fldManager.m_nFastLoadConIndex][i] = driver.NamedValue{Name:aBindValues[i].Name, Ordinal:aBindValues[i].Ordinal, Value:aBindValues[i].Value}
		}

		fldManager.m_nCurrentRowNumber++
		aBindValuesInternal[fldManager.m_nFastLoadConIndex] = append(aBindValuesInternal[fldManager.m_nFastLoadConIndex],
			driver.NamedValue{Ordinal:(len(aBindValues) + 1), Value:NewTeradataValueInteger(fldManager.m_nCurrentRowNumber)})

		if fldManager.m_appCon.hasDebugLog () {
			for i := 0; i < len(aBindValuesInternal); i++ {
				for j := 0; j < len(aBindValuesInternal[i]); j++ {
					var metadata string
					if j < len(fldManager.m_aBindMetadata) {
						metadata = fmt.Sprintf("m_aBindMetadata[%v]=%v", j, fldManager.m_aBindMetadata[j])
					} else {
						metadata = "appended RowNumber"
					}
					str := fmt.Sprintf("%v", aBindValuesInternal[i][j])
					strlen := int(math.Min(float64(50), float64(len(str))))
					debugLog(fmt.Sprintf("FastLoadManager.distributeRows m_sTableName=%v m_nFastLoadConIndex=%v %v %T%v aBindValuesInternal[%v][%v]=%T%v (len=%v)",
						fldManager.m_sTableName, fldManager.m_nFastLoadConIndex, metadata, aBindValuesInternal[i][j].Value,
						fldManager.getTeradataValueTypeName(aBindValuesInternal[i][j].Value), i, j, aBindValuesInternal[i][j], str[:strlen], len(str)))
				}
			}
		}

		numRowsInFastLoadCon[fldManager.m_nFastLoadConIndex]++
		fldManager.m_nFastLoadConIndex++
		if fldManager.m_nFastLoadConIndex >= len(fldManager.m_fastloadCon) {
			fldManager.m_nFastLoadConIndex = 0
		}
	}

	for i := range numRowsInFastLoadCon {
		if numRowsInFastLoadCon[i] > 0 {
			numFastloadConsToBeUsed++
		}
	}

	return

} // end method distributeRows

func (fldManager *fastLoadManagerBase) getTeradataValueTypeName(x any) (string) {

	var sTypeName string
	switch typedval := x.(type) {
		case TeradataValue:
			_, _, _, _, sTypeName = dataTypeInfo(typedval.CookedDataType())
			sTypeName = "("+sTypeName+")"
	}
	return sTypeName

} // end getTeradataValueTypeName

func (fldManager *fastLoadManagerBase) getTeradataTypeName(cookedDataType uint16) (string) {

	_, _, _, _, sTypeName := dataTypeInfo(cookedDataType)
	return sTypeName

} // end getTeradataTypeName
